package strategy;
public class WinningStrategy implements Strategy {
 private boolean won;
 private Hand previousHand;
 public Hand nextHand() {
  if (!won) previousHand = Hand.getHand(random.nextInt(3));
  return previousHand;
 }
 public void study(boolean win) { won = win; }
}

